/** Currency Management View — Exchange rates, multi-currency conversion, base currency settings. Data: /api/v1/currency/* */
import React, { useState, useEffect, useCallback } from 'react';
import { DollarSign, RefreshCw } from 'lucide-react';
import api from '../services/api';
interface CurrencyRate { id: string; code: string; name: string; rate_to_base: number; last_updated?: string; }
const CurrencyView: React.FC = () => {
  const [items, setItems] = useState<CurrencyRate[]>([]);
  const [loading, setLoading] = useState(true);
  const fetch = useCallback(async () => { setLoading(true); try { const d = await api.get('/currency/'); setItems(d.data || []); } catch (e) { console.error(e); } finally { setLoading(false); } }, []);
  useEffect(() => { fetch(); }, [fetch]);
  if (loading) return <div className="flex items-center justify-center h-full text-text-ops-muted">Loading currency data...</div>;
  return (
    <div className="flex flex-col h-full">
      <div className="flex items-center justify-between px-6 py-4 border-b border-border-ops-subtle">
        <div className="flex items-center gap-3"><DollarSign className="w-6 h-6 text-yellow-400" /><div><h1 className="text-lg font-semibold text-text-ops-primary">Currency Management</h1><p className="text-sm text-text-ops-muted">Exchange Rates &amp; Multi-Currency</p></div></div>
        <button onClick={fetch} className="p-2 rounded hover:bg-bg-ops-overlay text-text-ops-muted hover:text-text-ops-primary"><RefreshCw className="w-4 h-4" /></button>
      </div>
      <div className="flex-1 overflow-auto p-6"><table className="w-full text-sm"><thead><tr className="border-b border-border-ops-subtle text-text-ops-muted"><th className="text-left py-2 px-3 font-medium">Code</th><th className="text-left py-2 px-3 font-medium">Name</th><th className="text-right py-2 px-3 font-medium">Rate to Base</th><th className="text-left py-2 px-3 font-medium">Last Updated</th></tr></thead><tbody>
        {items.map(i => (<tr key={i.id} className="border-b border-border-ops-subtle hover:bg-bg-ops-overlay"><td className="py-2 px-3 font-mono text-text-ops-primary">{i.code}</td><td className="py-2 px-3 text-text-ops-primary">{i.name}</td><td className="py-2 px-3 text-right font-mono text-text-ops-primary">{i.rate_to_base.toFixed(4)}</td><td className="py-2 px-3 text-text-ops-muted text-xs">{i.last_updated || '—'}</td></tr>))}
        {items.length === 0 && <tr><td colSpan={4} className="py-8 text-center text-text-ops-muted">No currency rates configured.</td></tr>}
      </tbody></table></div>
    </div>
  );
};
export default CurrencyView;
